SELECT $this ?value (<http://example.org/ns/schema#lifecycleStage> AS ?path)
WHERE {
  $this <http://example.org/ns/schema#lifecycleStage> ?value .
  FILTER NOT EXISTS { ?value a <http://www.w3.org/2004/02/skos/core#Concept> ; <http://www.w3.org/2004/02/skos/core#inScheme> <http://example.org/ns/vocab#Lifecycle> }
}

